// def relay(xs: Iterable[int32]) -> Iterator[int32]:
//     for x in xs:
//         yield x                                     # -> S_RESUME_0
template <::tpystd::typing::Iterable<int32_t> T_xs>
std::expected<int32_t, ::tpy::StopIteration> __gen_relay<T_xs>::__next__() {
    while (true) switch (__state) {
    case S_INITIAL: {  // entry
        __state = S_DONE;  // until a yield sets where to resume
        ::tpy::resumable_iter_init(__for_itr_0, xs);
        __state = S_JOIN_0;
        continue;
    }
    case S_RESUME_0:  // after: yield x
    case S_JOIN_0: {
        __for_r_0.emplace(::tpy::resumable_iter_next(__for_itr_0, xs));
        if (!(*__for_r_0).has_value()) {
            __state = S_DONE;
            return ::tpy::make_unexpected(::tpy::StopIteration{});
        }
        x = ::tpy::unwrap_ref(*(*__for_r_0));
        __state = S_RESUME_0;
        return x;
    }
    case S_DONE: return ::tpy::make_unexpected(::tpy::StopIteration{});
    }
    __builtin_unreachable();
}


// def relay(xs: Iterable[int32]) -> Iterator[int32]:
template <::tpystd::typing::Iterable<int32_t> T_xs>
__gen_relay<T_xs> relay(T_xs&& xs) {
    return __gen_relay<T_xs>(std::forward<T_xs>(xs));
}

